// The Worker's bindings, vars and secrets, and the Hono context types.
//
// Runtime types (D1Database, DurableObjectNamespace, ...) come from
// worker-configuration.d.ts, generated by `npm run cf-typegen`
// (`wrangler types --include-env=false`). The Env interface itself is written
// by hand here, so it is the contract: when wrangler.jsonc gains a binding,
// add it here in the same change.

import type { Matchmaker } from "./do/matchmaker";
import type { MatchRoom } from "./do/match-room";

export interface AppBindings {
  // Bindings (wrangler.jsonc)
  DB: D1Database;
  /** Avatars at avatars/<userId>/<random>.jpg. */
  AVATARS: R2Bucket;
  MATCH_ROOM: DurableObjectNamespace<MatchRoom>;
  MATCHMAKER: DurableObjectNamespace<Matchmaker>;
  /** Delivers to arbitrary addresses only once the domain is onboarded. Failures are logged, never thrown. */
  EMAIL: SendEmail;
  /** Keyed by cf-connecting-ip on sign-up, sign-in and password reset. */
  AUTH_LIMITER: RateLimit;
  /** Keyed by `<action>:<userId>` on lobby creation and joins, bot matches, queue and match sockets, and reports. */
  API_LIMITER: RateLimit;

  // Vars (wrangler.jsonc; .dev.vars overrides APP_URL locally)
  /** Public origin: the production URL from wrangler.jsonc, http://localhost:5173 in dev. */
  APP_URL: string;
  NOTES_URL: string;

  // Secrets (wrangler secret put; .dev.vars locally)
  BETTER_AUTH_SECRET: string;
  /** Google sign-in is hidden unless both are set. */
  GOOGLE_CLIENT_ID?: string;
  GOOGLE_CLIENT_SECRET?: string;
  /** "1" once the sending domain is onboarded in Cloudflare Email Service. */
  EMAIL_ENABLED?: string;
  /** "1" enables test mode (with a localhost request). Never set in production. */
  TEST_MODE?: string;
}

declare global {
  namespace Cloudflare {
    // `env` from "cloudflare:workers" and the test helpers are typed as Cloudflare.Env.
    interface Env extends AppBindings {}
    // Types `exports` from "cloudflare:workers" (exports.default.fetch in tests, ctx.exports).
    interface GlobalProps {
      mainModule: typeof import("./index");
      durableNamespaces: "MatchRoom" | "Matchmaker";
    }
  }
}

export type Env = Cloudflare.Env;

/** The signed-in user, as the session middleware puts it on the Hono context. */
export interface SessionUser {
  id: string;
  email: string;
  emailVerified: boolean;
  name: string;
  /** Null for Google users until onboarding. */
  username: string | null;
  displayUsername: string | null;
  firstName: string;
  lastName: string;
  image: string | null;
  role: string;
}

export interface AppVariables {
  /** Null when signed out. Routes that need a session use the requireUser middleware. */
  user: SessionUser | null;
  /** Better Auth session id; null when signed out. */
  sessionId: string | null;
}

/** Generic for every Hono app and router: `new Hono<HonoEnv>()`. */
export interface HonoEnv {
  Bindings: Env;
  Variables: AppVariables;
}
